x", "size": 13, "sizes": []}, "typography_font_weight": "400", "paragraph_spacing": {"unit": "px", "size": 0, "sizes": []}, "text_color": "#4E4E4E"}, "elements": [], "widgetType": "text-editor"}], "isInner": true}, {"id": "fc4e6a9", "elType": "container", "settings": {"margin": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": false}, "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "40", "left": "0", "isLinked": false}}, "elements": [{"id": "164b20b", "elType": "widget", "settings": {"shortcode": "[trustindex no-registration=google]"}, "elements": [], "widgetType": "shortcode"}], "isInner": false}, {"id": "rbo_home_compliance_framework_section", "elType": "container", "isInner": false, "settings": {"content_width": "full", "padding": {"unit": "px", "top": "10", "right": "0", "bottom": "25", "left": "0", "isLinked": false}}, "elements": [{"id": "rbo_home_compliance_widget", "elType": "widget", "widgetType": "html", "settings": {"html": "<div class="rbo-homepage-compliance-framework" dir="rtl" style="max-width: 1140px; margin: 45px auto; padding: 0 20px; font-family: 'Cairo', 'Tajawal', sans-serif; color: #1e293b; direction: rtl; text-align: right;">
  <section style="background: #ffffff; border-radius: 16px; border: 1px solid #e2e8f0; padding: 38px 30px; box-shadow: 0 10px 35px rgba(9, 32, 59, 0.06);">
    <div style="text-align: center; max-width: 820px; margin: 0 auto 32px;">
      <span style="background: rgba(201, 162, 39, 0.15); color: #9a731c; border: 1px solid rgba(201, 162, 39, 0.4); padding: 5px 16px; border-radius: 9999px; font-size: 13px; font-weight: 700; letter-spacing: 0.5px;">متطلبات الامتثال الضريبي والمالي لعام 2026 في الإمارات</span>
      <h2 style="font-family: 'Cairo', 'Tajawal', sans-serif; font-size: 30px; color: #09203b; margin: 14px 0 10px; font-weight: 800; line-height: 1.3;">الامتثال المالي المتكامل والتدقيق القانوني والحوكمة الضريبية</h2>
      <p style="color: #64748b; font-size: 15.5px; line-height: 1.6; margin: 0;">حلول امتثال مالي قانونية شاملة متوافقة مع لوائح الهيئة الاتحادية للضرائب (FTA)، وقرارات وزارة المالية، وقانون الشركات التجارية الإماراتي.</p>
    </div>

    <!-- 4-Pillar Grid in Arabic -->
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; margin-bottom: 35px;">
      <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 24px; text-align: right;">
        <div style="width: 44px; height: 44px; background: #09203b; border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #e8b84b; font-size: 18px; font-weight: 700; margin-bottom: 16px;">ض.ش</div>
        <h3 style="font-size: 18px; color: #09203b; margin: 0 0 10px; font-weight: 700;">إقرار ضريبة الشركات Form CT201</h3>
        <p style="color: #475569; font-size: 13.5px; line-height: 1.6; margin: 0 0 12px;">امتثال تام للمرسوم بقانون اتحادي رقم 47 لسنة 2022. تطبيق تسهيلات الأعمال الصغيرة (SBR) حتى 3 مليون درهم، وتدقيق شركات المناطق الحرة المؤهلة بنسبة 0% QFZP، وإثبات النفقات القابلة للخصم.</p>
        <a href="https://www.rboaccounting.ae/ar/corporate-tax-planning/" style="color: #0b3a6e; font-size: 13.5px; font-weight: 700; text-decoration: none;">خدمات ضريبة الشركات ←</a>
      </div>

      <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 24px; text-align: right;">
        <div style="width: 44px; height: 44px; background: #09203b; border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #e8b84b; font-size: 18px; font-weight: 700; margin-bottom: 16px;">ف.إ</div>
        <h3 style="font-size: 18px; color: #09203b; margin: 0 0 10px; font-weight: 700;">الفوترة الإلكترونية 2026 (Peppol)</h3>
        <p style="color: #475569; font-size: 13.5px; line-height: 1.6; margin: 0 0 12px;">الاستعداد لنظام الفوترة الإلكترونية المؤتمت الإلزامي الصادر عن وزارة المالية. ربط أنظمة ERP، وتنسيق صيغ XML/UBL، والتأهيل مع مزودي الخدمة المعتمدين.</p>
        <a href="https://www.rboaccounting.ae/ar/services/" style="color: #0b3a6e; font-size: 13.5px; font-weight: 700; text-decoration: none;">جاهزية الفوترة الإلكترونية ←</a>
      </div>

      <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 24px; text-align: right;">
        <div style="width: 44px; height: 44px; background: #09203b; border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #e8b84b; font-size: 18px; font-weight: 700; margin-bottom: 16px;">تدقيق</div>
        <h3 style="font-size: 18px; color: #09203b; margin: 0 0 10px; font-weight: 700;">التدقيق المالي القانوني المعتمد</h3>
        <p style="color: #475569; font-size: 13.5px; line-height: 1.6; margin: 0 0 12px;">إصدار تقارير تدقيق مالي قانونية معتمدة ومتوافقة مع معايير IFRS والحدود المالية المقررة (50 مليون درهم). متطلب إلزامي لتجديد الرخص التجارية في المناطق الحرة والبر الرئيسي.</p>
        <a href="https://www.rboaccounting.ae/ar/statutory-audit/" style="color: #0b3a6e; font-size: 13.5px; font-weight: 700; text-decoration: none;">خدمات التدقيق المعتمد ←</a>
      </div>

