": "custom", "typography_font_family": "Playfair Display", "typography_font_size": {"unit": "px", "size": 32, "sizes": []}, "typography_font_weight": "700", "align_mobile": "start", "typography_font_size_mobile": {"unit": "px", "size": 26, "sizes": []}, "typography_line_height": {"unit": "px", "size": 39, "sizes": []}, "typography_line_height_mobile": {"unit": "em", "size": 1.2, "sizes": []}, "__globals__": {"title_color": "globals/colors?id=secondary"}}, "elements": [], "widgetType": "heading"}, {"id": "8758a43", "elType": "widget", "settings": {"editor": "<div class="section-header center"><p class="section-subtitle">كل ما تسأل عنه الشركات في الإمارات حول المحاسبة وضريبة القيمة المضافة وضريبة الشركات — بإجابات واضحة ودقيقة.</p></div>", "align": "justify", "typography_typography": "custom", "typography_font_family": "Poppins", "typography_font_size_mobile": {"unit": "px", "size": 13, "sizes": []}, "typography_font_weight": "400", "paragraph_spacing": {"unit": "px", "size": 0, "sizes": []}, "text_color": "#4E4E4E"}, "elements": [], "widgetType": "text-editor"}], "isInner": true}, {"id": "514078af", "elType": "widget", "settings": {"tabs": [{"_id": "6fc1e8b", "tab_title": "ما الذي يجعل شركة RBO إحدى أبرز وأفضل شركات المحاسبة والتدقيق في الإمارات؟", "tab_content": "<p>تجمع شركة RBO بين الوكلاء الضريبيين المعتمدين من الهيئة الاتحادية للضرائب (FTA)، والمدققين الماليين المعتمدين، وفريق ذو خبرة عملية واسعة في اللوائح الضريبية الإماراتية. نقدم حلولاً شاملة تشمل مسك الدفاتر، والتخطيط لضريبة الشركات (9%)، وإقرارات ضريبة القيمة المضافة، والتدقيق القانوني المعتمد، وإدارة الرواتب عبر WPS — بأسعار شهرية ثابتة وشفافة وبدون أي رسوم خفية.</p>"}, {"_id": "25c06da", "tab_title": "ما هي باقة خدمات المحاسبة والضرائب والتدقيق الشاملة التي تقدمونها في الإمارات؟", "tab_content": "<p>نتولى تسجيل ضريبة القيمة المضافة من اليوم الأول، وإعداد وتقديم الإقرارات الدورية، ومتابعة استرداد الضريبة المستحقة. كما يقدم خبراؤنا استشارات ضريبية متخصصة، ودعم التدقيق الضريبي لدى الهيئة الاتحادية للضرائب FTA.</p>"}, {"_id": "6943648", "tab_title": "كم تبلغ تكلفة الاستعانة بشركة خارجية لخدمات المحاسبة ومسك الدفاتر في الإمارات؟", "tab_content": "<p>نقدم باقات شهرية مخصصة وشفافة تعتمد على حجم المعاملات ونشاط الشركة وعدد الموظفين، وتبدأ الباقات الأساسية للشركات الصغيرة والمتوسطة من أسعار تنافسية وثابتة شهرياً تشمل كافة التقارير الدورية دون أي تكاليف خفية، مما يوفر أكثر من 60% من تكلفة تعيين قسم محاسبي داخلي بدوام كامل.</p>"}, {"_id": "259cf57", "tab_title": "لماذا يعد تعيين وكيل ضريبي معتمد من الهيئة الاتحادية للضرائب أمراً حيوياً للشركات؟", "tab_content": "<p>وفقاً للمرسوم بقانون اتحادي رقم 28 لسنة 2022 بشأن الإجراءات الضريبية، فإن الوكيل الضريبي المعتمد فقط هو المرخص له رسمياً بتمثيل شركتك أمام الهيئة الاتحادية للضرائب والرد على استفسارات مفتشي الضرائب، وتقديم طلبات إعادة النظر في الغرامات، مما يحمي شركتك من الأخطاء والغرامات الإدارية الباهظة.</p>"}, {"_id": "1125010", "tab_title": "كيف يؤثر نظام الفوترة الإلكترونية الإلزامي في الإمارات على محاسبة شركتنا؟", "tab_content": "<p>يلزم نظام الفوترة الإلكترونية الوطني الصادر عن وزارة المالية والهيئة الاتحادية للضرائب كافة الشركات بإصدار فواتير رقمية متوافقة لحظياً بنظام B2B. يساعدك فريق RBO في تأهيل نظامك المحاسبي وربط برنامجك المالي لتوليد صيغ الفواتير الإلكترونية المعتمدة وضمان الامتثال التام قبل المواعيد الإلزامية.</p>"}, {"_id": "a4c7248", "tab_title": "متى يكون التدقيق المالي السنوي إلزامياً لشركات البر الرئيسي والمناطق الحرة؟", "tab_content": "<p>بموجب قانون الشركات التجارية الإماراتي واللوائح التنظيمية لمعظم سلطات المناطق الحرة (مثل عجمان AFZA، دبي DAFZA/JAFZA، وغيرها)، يعد التدقيق المالي القانوني السنوي من مدقق معتمد شرطاً أساسياً لتجديد الرخصة التجارية، وتوزيع الأرباح، وتقديم التسهيلات البنكية، وتأكيد الوضع المالي أمام الشركاء والمستثمرين.</p>"}, {"_id": "a4b96c3", "tab_title": "كيف تساعد RBO الشركات في تسجيل ضريبة الشركات وتقديم إقرار CT201 السنوي؟", "tab_content": "<p>نتولى دورة ضريبة الشركات كاملة: تسجيل المنشأة عبر منصة إمارات تاكس (EmaraTax)، وإصدار الرقم الضريبي للشركات، وإجراء التعديلات المحاسبية المعتمدة وفق القانون، وإعداد وتقديم الإقرار الضريبي السنوي Form CT201 قبل انتهاء مهلة الـ 9 أشهر المحددة قانوناً، مع دراسة الخيارات المؤهلة للإعفاءات وضريبة الصفر بالمائة.</p>"}, {"_id": "9b11037", "tab_title": "ما هي شروط الاستفادة من نسبة 0% لضريبة الشركات في المناطق الحرة (شخص مؤهل QFZP)؟", "tab_content": "<p>للاستفادة من نسبة 0%، يجب أن تحقق الشركة شروط الشخص المؤهل في المنطقة الحرة: الحفاظ على وجود اقتصادي كافٍ (نفقات وموظفون مؤهلون)، وتحقيق دخل مؤهل من أنشطة مؤهلة، والالتزام بمتطلبات التسعير التحويلي، وإعداد بيانات مالية مدققة. يقوم مستشارونا بمراجعة نشاط شركتك لضمان تحقيق كافة الشروط بدقة.</p>"}, {"_id": "8a04933", "tab_title": "كيف تضمن RBO امتثال شركتك لنظام حماية الأجور (WPS) وقوانين العمل؟", "tab_content": "<p>نقوم بإعداد مسيرات الرواتب الشهرية بصيغة SIF المعتمدة، وضمان تحويل الرواتب عبر البنوك المعتمدة ومحلات الصرافة في المواعيد المقررة، واحتساب مكافأة نهاية الخدمة بدقة وفق قانون تنظيم علاقات العمل الاتحادي، مما يحميك من إيقاف ملف المنشأة لدى وزارة الموارد البشرية والتوطين (MOHRE).</p>"}, {"_id": "f1a2304", "tab_title": "كيف يمكن لشركتنا الانتقال إلى RBO بسلاسة ودون أي انقطاع في سير العمل أو فقدان للبيانات؟", "tab_content": "<p>تضمن منهجية الانتقال لدينا عدم توقف عملياتك إطلاقاً؛ حيث ننسق استلام موازين المراجعة والسجلات التاريخية والملفات الضريبية السابقة من مزودك القديم، ومطابقتها وتدقيق أرصدتها الافتتاحية وربطها بنظامك المحاسبي السحابي الجديد خلال أيام قليلة ودون أي جهد من جانبك.</p>"}], "selected_icon": {"value": "fas fa-angle-double-down", "library": "fa-solid"}, "selected_active_icon": {"value": "fas fa-angle-double-up", "library": "fa-solid"}, "title_background": "#0D1B2A", "title_color": "#E8B84B", "tab_active_color": "#E8B84B", "title_typography_typography": "custom", "title_typography_font_family": "Playfair Display", "title_typography_font_size": {"unit": "px", "size": 15, "sizes": []}, "title_typography_font_size_mobile": {"unit": "px", "size": 13, "sizes": []}, "title_typography_font_weight": "600", "title_typography_letter_spacing": {"unit": "px", "size"